with tempfile.TemporaryDirectory(prefix='community-test-') as tmp:
 paths=[]
 for name,text in stubs.items():
  p=pathlib.Path(tmp,name);p.parent.mkdir(parents=True,exist_ok=True);p.write_text(text,encoding="utf8");paths.append(str(p))
 paths += [str(base/'org/telegram/messenger'/n) for n in ('CommunityQuickPhrases.java','CommunityDownloadPolicy.java')]
 subprocess.run(['javac','-encoding','UTF-8','-d',tmp,*paths],check=True)
 subprocess.run(['java','-cp',tmp,'CommunityTest'],check=True)
chat=(base/'org/telegram/ui/ChatActivity.java').read_text(encoding='utf8')
handler=chat.split('if (id == telebots_quick_phrases) {',1)[1].split('if (id == -1)',1)[0]
